import argparse, hashlib, json, re, subprocess
from datetime import UTC, datetime
from pathlib import Path

ROOT=Path('/workspace/tiny-perceptron-vlm')
def sha(raw):return hashlib.sha256(raw).hexdigest()
p=argparse.ArgumentParser()
p.add_argument('--stage',choices=['reader','technical','all'],default='all')
p.add_argument('--output',type=Path)
a=p.parse_args()
stages=['reader','technical'] if a.stage=='all' else [a.stage]
records=[]; errors=[]
for stage in stages:
    journals=[]
    for path in sorted((ROOT/'docs/course-experiments/review-dispatch').glob('*.json')):
        data=json.loads(path.read_bytes())
        events=[e for e in data.get('events',[]) if e.get('stage',data.get('stage'))==stage]
        if events:journals.append((path,data,events))
    baseline=json.loads((ROOT/'docs/course-experiments/review-round-baseline.json').read_bytes())
    for lesson in baseline['records']:
        report_path=ROOT/f'docs/{stage}-reviews/{lesson}.json'
        if not report_path.is_file():errors.append(f'{stage}/{lesson}: missing report');continue
        report_raw=report_path.read_bytes();r=json.loads(report_raw);task=r['reviewer_task']
        source=ROOT/r['source'].split('#')[0];raw=source.read_bytes()
        hs=list(re.finditer(rb'(?m)^## ([A-Z\d]+\.\d+) [^\r\n]+',raw))
        i=next(i for i,h in enumerate(hs) if h[1].decode()==lesson)
        current=sha(raw[hs[i].start():hs[i+1].start() if i+1<len(hs) else len(raw)])
        if r.get('source_sha256')!=current or r.get('verdict')!='pass':errors.append(f'{stage}/{lesson}: current section not passed');continue
        dispatches=[];results=[]
        for path,data,events in journals:
            own=[e for e in events if e.get('lesson_id')==lesson and (e.get('reviewer_task') or e.get('child_task'))==task]
            for e in own:
                if e.get('event') in {'dispatch','spawn'} and (e.get('fork_turns')=='none' or e.get('fresh_context') is True):dispatches.append((path,e))
                if e.get('event') in {'result','recheck_result'} and (e.get('verdict') or e.get('result'))=='pass':
                    if e.get('report_sha256')==sha(report_raw):results.append((path,e,'exact_report_sha256'))
                    elif 'report_sha256' not in e and e.get('source_sha256')==current:results.append((path,e,'current_section_sha256_in_earlier_journal_schema'))
                    elif stage=='reader' and 'report_sha256' not in e and 'source_sha256' not in e and e.get('report')==report_path.relative_to(ROOT).as_posix():results.append((path,e,'report_path_only_in_earliest_journal_schema_no_historical_hash'))
        if not dispatches or not results:errors.append(f'{stage}/{lesson}: no matching actual fresh dispatch/current pass consumption');continue
        dp,de=dispatches[-1];rp,re_,basis=results[-1]
        records.append({'stage':stage,'lesson_id':lesson,'reviewer_task':task,'source_sha256':current,'report_sha256':sha(report_raw),'dispatch_journal':dp.relative_to(ROOT).as_posix(),'dispatch_event':de,'result_journal':rp.relative_to(ROOT).as_posix(),'result_event':re_,'result_version_matching':basis})
if errors:
    print('\n'.join(errors));raise SystemExit(1)
result={'schema_version':1,'checked_at':datetime.now(UTC).isoformat(),'status':'passed','stage':a.stage,'scope':'Read-only matching of current passed reports to recorded real fresh-agent dispatch and result consumption. Earliest reader journals name only consumed report paths and cannot establish a historical report hash; later reader journals identify section hashes or complete report hashes. Every technical result must identify its complete report hash. Current raw sections are checked separately here and by content/introduction gates. This check cannot independently prove reading, source verification, or report authorship; those require the actual agent transcript. It never writes reviews or verdicts.','checkout_revision':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'verification_program':Path(__file__).read_text(),'record_count':len(records),'records':records}
if a.output:
    a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'status':'passed','stage':a.stage,'records':len(records)}))
